import { definitionSetup } from '../../utils'

/** A vocabulary: names, and the strings a meta uses for them. */
type Vocabulary = Record<string, string>

/** A handler, validator or value transform a meta names: called with whatever its caller passes. */
type Registered = (...args: any[]) => any

/** What is registered on `FIELD` besides the three vocabularies `definitionSetup` makes. */
type FieldRegistries = {
  /** Action handlers by `FIELD.ACTION` name; each document registers its own */
  FUNC: Record<string, Registered>
  /** Validator names, and the validators they select: `modules/form/constants` registers both */
  VALIDATE: Record<string, string>
  VALIDATION: Record<string, Registered>
  /** The engine's own registries, from `engine/rules`: a cross-row validator's name, and value transforms */
  CROSS_VALIDATE: Record<string, string>
  NORMALIZE: Record<string, string>
  NORMALIZER: Record<string, Registered>
  PARSER: Record<string, Registered>
  /** The host's `methods`, by name: each document registers its own */
  METHODS: Record<string, Registered>
}

/**
 * FIELD DEFINITIONS ===========================================================
 */
// A cast, not a guard: every vocabulary below holds strings, and the registries are plain
// properties, assigned while the modules load.
export const FIELD = definitionSetup('TYPE', 'RENDER', 'ACTION') as Record<'TYPE' | 'RENDER' | 'ACTION', Vocabulary> & FieldRegistries

// Field Type Definitions
FIELD.TYPE = {
  BUTTON: 'Button',
  EXPAND: 'Expand', // Expandable/collapsing content with clickable `title` or `renderLabel` area
  EXPAND_LIST: 'ExpandList', // list of Expand components with dynamic `renderLabel` and `renderItem` attributes
  CHECKBOX: 'Checkbox', // checkbox with optional label
  COL: 'Col', // Vertical column layout
  COL2: 'Column', // alias for Column
  COL3: 'VerticalLayout', // alias for Column
  COL_LIST: 'ColList', // alias for List
  COL_LIST3: 'VerticalList', // alias for List
  COUNTER: 'Counter', // Animated number changing from `start` to `end` values
  DROPDOWN: 'Dropdown', // in-house, `components/Dropdown.tsx`
  LABEL: 'Label',
  LIST: 'List', // list of Col components with dynamic `renderItem` attributes
  PIE_CHART: 'PieChart', // Pie chat (can be in shape of donut) with optional legends
  PROGRESS_STEPS: 'ProgressSteps', // Progress Steps, with content like Tabs
  ROW: 'Row', // Horizontal row layout
  ROW2: 'HorizontalLayout', // alias for Row
  ROW_LIST: 'RowList', // alias for List with Row layout
  ROW_LIST2: 'HorizontalList', // alias for List with Row layout
  SPACE: 'Space', // for adding space between items
  TABLE: 'Table',
  TABS: 'Tabs',
  TAB_LIST: 'TabList',
  TEXT: 'Text',
  TITLE: 'Title', // A customised `Text` view with certain styling for consistent look and feel
  TOOLTIP: 'Tooltip', // A hint components that pops up when element is being hovered
  // Declared here rather than in `engine/rules.tsx`, which used to register them (§9.3 step 2).
  // `engine/mapper.tsx` dispatches on all six, and `rules.tsx` imports `mapper.tsx` — so the resolver
  // depended on a constant its own importer installed. With the `engine` <-> `modules/form` cycle
  // gone, anything that loaded the mapper without also loading `rules.tsx` got a resolver whose
  // `case` for each of these compared against `undefined`, silently making six documented views
  // unreachable. Two mapper tests found it immediately; a consumer would have found it later.
  // Declared here rather than in `modules/form/constants.ts`, which used to register them
  // (§9.3 step 3): `engine/formData.ts` compares a meta node against `FIELD.TYPE.SELECT`, so that
  // comparison depended on whether anything had imported the form module yet.
  INPUT: 'Input', // generic input of different types (i.e. type='text', 'textarea', etc.)
  SELECT: 'Select', // dropdown / listbox field
  SLIDER: 'SliderLabel', // slider field with label
  TOGGLE: 'Toggle', // checkbox rendered as toggle button
  UPLOAD: 'Upload',  // single file upload with drag & drop
  AUTO_SUBMIT: 'AutoSubmit',
  DATA: 'Data',
  ICON: 'Icon',
  IMAGE: 'Image',
  POPUP: 'Popup',
  TABLE_CELLS: 'TableCells',
}

// Value Renderer Definitions
FIELD.RENDER = {
  CURRENCY: 'Currency',
  PERCENT: 'Percent',
  DOUBLE5: 'Double5',
  FLOAT: 'Float',
  TITLE_n_INPUT: 'Title+Input',
  STRING: 'String',
  DATE: 'Date'
}

// Action Type Definitions
FIELD.ACTION = {
  RESET: 'reset',
  SET_STATE: 'setState',
  FETCH: 'fetch',
  POPUP: 'popup',
  WARN: 'warn',
}

// Action Methods by Action Type Definitions
FIELD.FUNC = {
  [FIELD.ACTION.WARN]: console.warn,
}
